//! Unforgeable identity for one native WebView session.
//!
//! A 128-bit token is generated by the native host and injected only into the
//! top-level shell after navigation. The engine iframe never receives it. A
//! second 128-bit id names the one document the session may read; the native
//! handler answers that path only while the session is current.

use std::fmt;
use std::io;
use std::sync::Arc;

#[derive(Clone, Copy, PartialEq, Eq)]
pub struct SessionId([u8; 16]);

impl SessionId {
    pub fn random() -> io::Result<Self> {
        let mut bytes = [0u8; 16];
        getrandom::fill(&mut bytes)
            .map_err(|error| io::Error::other(format!("no session entropy: {error}")))?;
        Ok(Self(bytes))
    }

    pub fn parse(hex: &str) -> Option<Self> {
        let bytes = hex.as_bytes();
        if bytes.len() != 32 {
            return None;
        }
        let mut out = [0u8; 16];
        for (index, chunk) in bytes.chunks_exact(2).enumerate() {
            out[index] = (lower_hex(chunk[0])? << 4) | lower_hex(chunk[1])?;
        }
        Some(Self(out))
    }

    pub fn hex(self) -> String {
        let mut text = String::with_capacity(32);
        for byte in self.0 {
            text.push(char::from(HEX[(byte >> 4) as usize]));
            text.push(char::from(HEX[(byte & 0xf) as usize]));
        }
        text
    }

    pub fn document_path(self) -> String {
        format!("/drawio/session/{}/document", self.hex())
    }
}

impl fmt::Debug for SessionId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("SessionId(redacted)")
    }
}

/// The shell's bearer token. Deliberately opaque: no `Debug`, `Display` or
/// `Serialize` implementation can put it in a log line.
#[derive(Clone, Copy)]
pub struct SessionToken([u8; 16]);

impl SessionToken {
    pub fn random() -> io::Result<Self> {
        let mut bytes = [0u8; 16];
        getrandom::fill(&mut bytes)
            .map_err(|error| io::Error::other(format!("no token entropy: {error}")))?;
        Ok(Self(bytes))
    }

    pub fn hex(self) -> String {
        let mut text = String::with_capacity(32);
        for byte in self.0 {
            text.push(char::from(HEX[(byte >> 4) as usize]));
            text.push(char::from(HEX[(byte & 0xf) as usize]));
        }
        text
    }

    /// Compares the wire spelling without an early exit. A wrong token is not
    /// a reason to reveal how many leading digits matched.
    pub fn matches(&self, candidate: &str) -> bool {
        let bytes = candidate.as_bytes();
        if bytes.len() != 32 {
            return false;
        }
        let mut diff = 0u8;
        for (index, byte) in bytes.iter().enumerate() {
            let expected = self.0[index / 2];
            let expected = if index % 2 == 0 {
                expected >> 4
            } else {
                expected & 0xf
            };
            let actual = lower_hex(*byte).unwrap_or(0xff);
            diff |= expected ^ actual;
        }
        diff == 0
    }
}

const HEX: &[u8; 16] = b"0123456789abcdef";

fn lower_hex(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        _ => None,
    }
}

/// The one document a live session may fetch.
#[derive(Clone)]
pub struct DocumentSession {
    pub id: SessionId,
    pub body: Arc<[u8]>,
}

impl DocumentSession {
    pub fn new(body: Arc<[u8]>) -> io::Result<Self> {
        Ok(Self {
            id: SessionId::random()?,
            body,
        })
    }

    pub fn path(&self) -> String {
        self.id.document_path()
    }
}

/// What the engine page should use as its `color-scheme`. The viewer's own
/// `light-dark()` rules follow it; the workbench chrome follows the theme it
/// already draws.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PreviewTheme {
    Light,
    Dark,
}

impl PreviewTheme {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Light => "light",
            Self::Dark => "dark",
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn session_ids_round_trip_and_reject_bad_spellings() {
        let id = SessionId::random().unwrap();
        assert_eq!(SessionId::parse(&id.hex()), Some(id));
        assert!(SessionId::parse(&id.hex().to_uppercase()).is_none());
        assert!(SessionId::parse("../../etc/passwd").is_none());
        assert!(SessionId::parse(&id.hex()[..30]).is_none());
    }

    #[test]
    fn token_comparison_is_exact_and_wire_shaped() {
        let token = SessionToken::random().unwrap();
        assert!(token.matches(&token.hex()));
        assert!(!token.matches(&token.hex().to_uppercase()));
        assert!(!token.matches("0"));
        let mut altered = token.hex().into_bytes();
        altered[31] = if altered[31] == b'0' { b'1' } else { b'0' };
        assert!(!token.matches(std::str::from_utf8(&altered).unwrap()));
    }
}
